//! Runtime support for models generated by stanc-rs.
//!
//! A generated model is a Rust module that depends on this crate and on stanmath-rs. It implements
//! [`GeneratedModel`], whose log density is generic in the scalar type so that the same code runs
//! with `f64` values and with stanmath-rs reverse-mode variables. Every [`GeneratedModel`] is also a
//! [`Model`], the object-safe interface that inference code uses.
//!
//! This crate is a minimal model runtime contract. It is meant to move into the future
//! `stan-model-rs` project once that exists; see `docs/runtime-contract.md`.

#![allow(missing_docs)]

pub mod check;
pub mod data;
pub mod index;
pub mod io;
pub mod names;
pub mod ops;
pub mod stan;

use std::fmt;

pub use rand;
pub use serde_json;
pub use stanmath_rs;

use stanmath_rs::prelude::try_value_and_grad;

/// What went wrong while evaluating a model.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ErrorKind {
    /// Input data is missing, malformed, has the wrong shape, or violates its constraints.
    Data,
    /// A function argument or a declared constraint was violated while evaluating the model
    /// (Stan rejects the current parameter values).
    Domain,
    /// An index was out of range.
    Index,
    /// Containers had inconsistent sizes.
    Size,
    /// The program called `reject`.
    Reject,
    /// The program called `fatal_error`; inference must stop.
    Fatal,
    /// The parameter vector had the wrong length.
    Parameters,
}

/// An error raised while running a generated model.
#[derive(Clone, Debug, PartialEq)]
pub struct ModelError {
    /// Classification.
    pub kind: ErrorKind,
    /// Explanation.
    pub message: String,
}

impl ModelError {
    /// Creates an error.
    pub fn new(kind: ErrorKind, message: impl Into<String>) -> Self {
        ModelError {
            kind,
            message: message.into(),
        }
    }

    /// A data error.
    pub fn data(message: impl Into<String>) -> Self {
        Self::new(ErrorKind::Data, message)
    }

    /// A domain error.
    pub fn domain(message: impl Into<String>) -> Self {
        Self::new(ErrorKind::Domain, message)
    }

    /// Reclassifies a domain error as a data error (constraint violations while reading data or
    /// running the transformed data block are problems with the data).
    pub fn in_data(mut self) -> Self {
        if self.kind == ErrorKind::Domain {
            self.kind = ErrorKind::Data;
        }
        self
    }

    /// Returns the error with `context` prepended to its message.
    pub fn context(mut self, context: &str) -> Self {
        self.message = format!("{context}: {}", self.message);
        self
    }
}

impl fmt::Display for ModelError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

impl std::error::Error for ModelError {}

impl From<stanmath_rs::Error> for ModelError {
    fn from(e: stanmath_rs::Error) -> Self {
        let kind = match e {
            stanmath_rs::Error::DimensionMismatch { .. } => ErrorKind::Size,
            _ => ErrorKind::Domain,
        };
        ModelError::new(kind, e.to_string())
    }
}

/// Result alias for model code.
pub type Result<T, E = ModelError> = std::result::Result<T, E>;

/// Options for evaluating the log density.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct DensityOptions {
    /// Add the log absolute Jacobian determinant of the constraining transforms.
    pub jacobian: bool,
    /// Drop constant terms (Stan's `propto`): `~` statements and `_lupdf` calls drop the terms
    /// that do not depend on parameters.
    pub propto: bool,
}

impl Default for DensityOptions {
    /// Jacobian included, all constants kept.
    fn default() -> Self {
        DensityOptions {
            jacobian: true,
            propto: false,
        }
    }
}

/// Shape of one model variable.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct VarInfo {
    /// Name in the Stan program.
    pub name: String,
    /// Dimensions after flattening arrays, vectors, and matrices (empty for scalars).
    pub dims: Vec<usize>,
    /// Block the variable belongs to.
    pub block: VarBlock,
    /// The element type is complex (each element is written as its real and imaginary parts).
    pub complex: bool,
    /// The two innermost dimensions are a matrix (stored column-major).
    pub matrix: bool,
}

/// The block of an output variable.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum VarBlock {
    Parameters,
    TransformedParameters,
    GeneratedQuantities,
}

/// The interface implemented by generated code. Its log density is generic in the scalar type.
pub trait GeneratedModel {
    /// Model name.
    fn model_name(&self) -> &'static str;

    /// Number of unconstrained parameters.
    fn num_unconstrained(&self) -> usize;

    /// Log density at unconstrained parameters `theta`. With `propto`, the terms of `~`
    /// statements that depend only on data are dropped; this only has an effect when `T` is an
    /// autodiff type, so [`Model::log_density`] evaluates `propto` densities with autodiff.
    fn log_prob_generic<T: check::Scalar>(
        &self,
        theta: &[T],
        jacobian: bool,
        propto: bool,
    ) -> Result<T>;

    /// Constrained parameters, then (optionally) transformed parameters and generated quantities,
    /// each flattened in column-major order.
    fn write_array_impl(
        &self,
        theta: &[f64],
        include_tp: bool,
        include_gq: bool,
        rng: &mut dyn rand::Rng,
    ) -> Result<Vec<f64>>;

    /// Unconstrained parameters from constrained values given as JSON (CmdStan's data format).
    fn unconstrain_json(&self, values: &data::Data) -> Result<Vec<f64>>;

    /// Shapes of the output variables.
    fn var_info(&self) -> Vec<VarInfo>;
}

/// The object-safe model interface used by inference algorithms.
pub trait Model {
    /// Model name.
    fn name(&self) -> &str;

    /// Number of unconstrained parameters.
    fn num_unconstrained(&self) -> usize;

    /// Flattened names of the output values (`beta.1`, `Sigma.2.1`, ...), one-based and in the
    /// order of [`Model::write_array`].
    fn param_names(&self, include_tp: bool, include_gq: bool) -> Vec<String>;

    /// Names of the unconstrained parameters.
    fn unconstrained_param_names(&self) -> Vec<String>;

    /// Log density at unconstrained parameters.
    fn log_density(&self, theta: &[f64], opts: DensityOptions) -> Result<f64>;

    /// Log density and its gradient at unconstrained parameters.
    fn log_density_gradient(&self, theta: &[f64], opts: DensityOptions) -> Result<(f64, Vec<f64>)>;

    /// Constrained parameters, transformed parameters, and generated quantities.
    fn write_array(
        &self,
        theta: &[f64],
        include_tp: bool,
        include_gq: bool,
        rng: &mut dyn rand::Rng,
    ) -> Result<Vec<f64>>;

    /// Unconstrained parameters from constrained values given as JSON.
    fn unconstrain(&self, values: &data::Data) -> Result<Vec<f64>>;

    /// Shapes of the output variables.
    fn variables(&self) -> Vec<VarInfo>;
}

fn check_len(theta: &[f64], n: usize) -> Result<()> {
    if theta.len() != n {
        return Err(ModelError::new(
            ErrorKind::Parameters,
            format!(
                "expected {n} unconstrained parameters, found {}",
                theta.len()
            ),
        ));
    }
    Ok(())
}

impl<M: GeneratedModel> Model for M {
    fn name(&self) -> &str {
        self.model_name()
    }

    fn num_unconstrained(&self) -> usize {
        GeneratedModel::num_unconstrained(self)
    }

    fn param_names(&self, include_tp: bool, include_gq: bool) -> Vec<String> {
        names::flat_names(&self.var_info(), include_tp, include_gq)
    }

    fn unconstrained_param_names(&self) -> Vec<String> {
        (1..=GeneratedModel::num_unconstrained(self))
            .map(|i| format!("theta.{i}"))
            .collect()
    }

    fn log_density(&self, theta: &[f64], opts: DensityOptions) -> Result<f64> {
        check_len(theta, GeneratedModel::num_unconstrained(self))?;
        if opts.propto {
            // Dropping constants needs to know which values are parameters.
            let r = try_value_and_grad(|p| self.log_prob_generic(p, opts.jacobian, true), theta)?;
            Ok(r.value)
        } else {
            self.log_prob_generic(theta, opts.jacobian, false)
        }
    }

    fn log_density_gradient(&self, theta: &[f64], opts: DensityOptions) -> Result<(f64, Vec<f64>)> {
        check_len(theta, GeneratedModel::num_unconstrained(self))?;
        let r = try_value_and_grad(
            |p| self.log_prob_generic(p, opts.jacobian, opts.propto),
            theta,
        )?;
        Ok((r.value, r.gradient))
    }

    fn write_array(
        &self,
        theta: &[f64],
        include_tp: bool,
        include_gq: bool,
        rng: &mut dyn rand::Rng,
    ) -> Result<Vec<f64>> {
        check_len(theta, GeneratedModel::num_unconstrained(self))?;
        self.write_array_impl(theta, include_tp, include_gq, rng)
    }

    fn unconstrain(&self, values: &data::Data) -> Result<Vec<f64>> {
        self.unconstrain_json(values)
    }

    fn variables(&self) -> Vec<VarInfo> {
        self.var_info()
    }
}

/// Raises a `reject` error with the printed message.
pub fn reject<T>(message: String) -> Result<T> {
    Err(ModelError::new(ErrorKind::Reject, message))
}

/// Raises a `fatal_error` with the printed message.
pub fn fatal_error<T>(message: String) -> Result<T> {
    Err(ModelError::new(ErrorKind::Fatal, message))
}
